package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import javax.xml.namespace.QName;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.PropertyOwnerPointer;
import org.apache.commons.jxpath.ri.model.beans.NullPropertyPointer;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen2Test {

    @Test
    public void testCreatePath_IsAttribute_ReturnsAttribute() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);
        QName name = new QName("testAttr");

        // We need to mock the NullPropertyPointer behavior. 
        // Since isAttribute() isn't explicitly provided in the "Other methods" list 
        // but is used in the logic, we assume it's a method of the class.
        // However, the prompt implies we are testing the provided code.
        // In NullPropertyPointer, isAttribute() usually checks if it's an attribute.
        // Because we cannot easily mock the internal state of the class under test, 
        // we use Spy to control the behavior of isAttribute().

        NullPropertyPointer spyPointer = spy(new NullPropertyPointer(mockParent));
        doReturn(true).when(spyPointer).isAttribute();
        doReturn(name).when(spyPointer).getName();

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(eq(mockContext), eq(name))).thenReturn(mockAttributePointer);

        // Act
        NodePointer result = spyPointer.createPath(mockContext);

        // Assert
        assertNotNull(result);
        assertEquals(mockAttributePointer, result);
        verify(mockParent).createPath(mockContext);
        verify(mockNewParent).createAttribute(mockContext, name);
    }

    @Test
    public void testCreatePath_IsNotAttribute_ParentIsPropertyOwnerPointer() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);
        QName name = new QName("testProp");
        int index = 0;

        NullPropertyPointer spyPointer = spy(new NullPropertyPointer(mockParent));
        doReturn(false).when(spyPointer).isAttribute();
        doReturn(name).when(spyPointer).getName();
        doReturn(index).when(spyPointer).getIndex();

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        // Mock PropertyOwnerPointer behavior
        when(((PropertyOwnerPointer) mockNewParent).getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(eq(mockContext), eq(name), eq(index))).thenReturn(mockChildPointer);

        // Act
        NodePointer result = spyPointer.createPath(mockContext);

        // Assert
        assertNotNull(result);
        assertEquals(mockChildPointer, result);
        verify(mockNewParent).getPropertyPointer();
        verify(mockPropertyPointer).createChild(mockContext, name, index);
    }

    @Test
    public void testCreatePath_IsNotAttribute_ParentIsNotPropertyOwnerPointer() {
        // Arrange
        JXPathContext mockContext = mock(JXPathContext.class);
        NodePointer mockParent = mock(NodePointer.class);
        NodePointer mockNewParent = mock(NodePointer.class); // e.g., a DOMNodePointer
        QName name = new QName("testChild");
        int index = 5;

        NullPropertyPointer spyPointer = spy(new NullPropertyPointer(mockParent));
        doReturn(false).when(spyPointer).isAttribute();
        doReturn(name).when(spyPointer).getName();
        doReturn(index).when(spyPointer).getIndex();

        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createChild(eq(mockContext), eq(name), eq(index))).thenReturn(mockNewParent);

        // Act
        NodePointer result = spyPointer.createPath(mockContext);

        // Assert
        assertNotNull(result);
        assertEquals(mockNewParent, result);
        verify(mockNewParent).createChild(mockContext, name, index);
        verify(mockNewParent, never()).getPropertyPointer();
    }
}
